-- Aprenda se Divertindo · 51 · Trilha Policial · lote extra 5 (mesmos assuntos, novos ângulos) (100 questões)
-- Rode depois do 50-trilha-policial-4.sql. Cole tudo no SQL Editor e clique em Run. Rodar de novo apenas atualiza.

insert into public.questoes (id, materia, nivel, enunciado, opcoes, explicacao)
select id, materia, nivel, enunciado, opcoes, explicacao
from jsonb_to_recordset($q$[{"id":5739,"materia":"pen","nivel":0,"enunciado":"Qual destas situações NÃO é crime de furto?","opcoes":["Pegar o carro do vizinho com violência contra ele","Levar escondido um celular esquecido sobre a mesa do bar","Tirar dinheiro da carteira de alguém distraído","Subtrair ferramentas de uma obra à noite"],"explicacao":"Com violência ou grave ameaça contra a pessoa, o crime é roubo."},{"id":5740,"materia":"pen","nivel":0,"enunciado":"Rui empurra o homem que o agrediu no dia anterior, como revanche. Ele age em legítima defesa?","opcoes":["Não, porque a agressão já tinha acabado","Sim, sempre que houver agressão anterior","Sim, se ainda estiver com raiva","Sim, se a agressão tiver sido grave e recente"],"explicacao":"A legítima defesa exige agressão atual ou iminente; reagir depois é vingança."},{"id":5741,"materia":"pen","nivel":0,"enunciado":"Qual destas é uma causa que exclui a ilicitude (excludente de ilicitude)?","opcoes":["Estrito cumprimento do dever legal","Embriaguez voluntária por álcool ou substância","Arrependimento posterior","Confissão espontânea"],"explicacao":"As excludentes do art. 23: estado de necessidade, legítima defesa, estrito cumprimento do dever legal e exercício regular de direito."},{"id":5742,"materia":"pen","nivel":0,"enunciado":"O crime de roubo se diferencia do furto porque, no roubo, há:","opcoes":["Violência ou grave ameaça contra a pessoa","Apenas a subtração escondida","Engano da vítima, que entrega o bem por erro","Posse anterior do bem"],"explicacao":"Engano da vítima é estelionato; posse anterior, apropriação indébita."},{"id":5743,"materia":"pen","nivel":0,"enunciado":"Quem pratica o crime de concussão é, em regra:","opcoes":["Funcionário público","Qualquer particular, sem vínculo com o Estado","Apenas o juiz","Apenas o empresário"],"explicacao":"É crime próprio, praticado por funcionário público contra a Administração."},{"id":5744,"materia":"pen","nivel":1,"enunciado":"Um policial atira para impedir que um assaltante mate um refém. Sobre a conduta do policial, é correto afirmar que:","opcoes":["Ele age em legítima defesa de terceiro e não comete crime","Ele comete homicídio doloso, pois quis atirar no assaltante","Ele age em estado de necessidade putativo","Ele responde por excesso culposo, sempre"],"explicacao":"A legítima defesa pode proteger direito alheio."},{"id":5745,"materia":"pen","nivel":1,"enunciado":"Qual destas penas é privativa de liberdade?","opcoes":["Reclusão","Multa","Prestação de serviços à comunidade","Interdição temporária de direitos"],"explicacao":"As penas privativas de liberdade são reclusão e detenção."},{"id":5746,"materia":"pen","nivel":1,"enunciado":"A pena de reclusão pode começar a ser cumprida em regime:","opcoes":["Fechado, semiaberto ou aberto","Apenas aberto","Apenas semiaberto, com saídas temporárias","Somente domiciliar"],"explicacao":"A detenção começa no semiaberto ou no aberto, salvo regressão."},{"id":5747,"materia":"pen","nivel":1,"enunciado":"Para o Código Penal, considera-se praticado o crime no momento:","opcoes":["Da ação ou omissão, ainda que outro seja o do resultado","Do resultado, ainda que a ação tenha ocorrido muito tempo antes","Da sentença","Da denúncia"],"explicacao":"Art. 4º: teoria da atividade, quanto ao tempo do crime."},{"id":5748,"materia":"pen","nivel":1,"enunciado":"Para salvar um ferido, Lia quebra o vidro de um carro alheio e o usa para levá-lo ao hospital. Ela age em:","opcoes":["Estado de necessidade","Legítima defesa","Exercício regular de direito","Estrito cumprimento do dever legal"],"explicacao":"Sacrifica um bem (o carro) para salvar outro maior (a vida), diante de perigo atual que não provocou."},{"id":5749,"materia":"pen","nivel":2,"enunciado":"Ana subtraiu a bicicleta de um vizinho e, no mesmo dia, arrependida, devolveu-a intacta antes de qualquer investigação. Ela:","opcoes":["Responde por furto, com pena reduzida pelo arrependimento posterior","Não comete crime nenhum","Responde por roubo","Tem a punibilidade extinta pelo perdão expresso e formal da vítima ofendida"],"explicacao":"O furto já se consumou; a devolução voluntária antes da denúncia reduz a pena de 1 a 2/3."},{"id":5750,"materia":"pen","nivel":2,"enunciado":"No crime de peculato, o objeto desviado ou apropriado deve estar com o funcionário:","opcoes":["Em razão do cargo","Por empréstimo particular","Por herança","Por ter achado na rua"],"explicacao":"Art. 312: posse em razão do cargo."},{"id":5751,"materia":"pen","nivel":2,"enunciado":"Exigir dinheiro de um preso para não o transferir de cela, sendo agente penitenciário, é:","opcoes":["Concussão","Corrupção ativa","Prevaricação","Estelionato"],"explicacao":"Exigir vantagem em razão da função é concussão."},{"id":5752,"materia":"pen","nivel":2,"enunciado":"O particular que oferece dinheiro a um policial para não ser autuado comete:","opcoes":["Corrupção ativa","Corrupção passiva","Concussão","Prevaricação"],"explicacao":"Corrupção ativa: oferecer ou prometer vantagem a funcionário público (art. 333)."},{"id":5753,"materia":"pen","nivel":3,"enunciado":"Se o policial aceita o dinheiro oferecido e, por isso, deixa de autuar o infrator, a pena da corrupção passiva:","opcoes":["Aumenta de 1/3, porque ele deixou de praticar ato de ofício","Diminui pela metade, por ele ter sido induzido pelo particular","Fica igual","É substituída por multa"],"explicacao":"Art. 317, § 1º, do Código Penal."},{"id":5754,"materia":"pen","nivel":3,"enunciado":"Um batedor de carteira enfia a mão no bolso da vítima, mas o bolso estava vazio. Segundo o Código Penal, trata-se de:","opcoes":["Crime impossível, se o bolso estava totalmente vazio","Furto tentado, sempre","Furto consumado","Roubo tentado"],"explicacao":"Impropriedade absoluta do objeto (art. 17): não há o que furtar."},{"id":5755,"materia":"pen","nivel":3,"enunciado":"Léo quebra a janela de uma casa para furtar, mas desiste por vontade própria e vai embora sem levar nada. Ele responde:","opcoes":["Apenas pelo dano à janela","Por tentativa de furto, pois iniciou a execução","Por furto consumado","Por nada, pois desistiu"],"explicacao":"Desistência voluntária: responde só pelos atos já praticados (art. 15)."},{"id":5756,"materia":"pen","nivel":4,"enunciado":"Após envenenar a vítima, o agente se arrepende, dá a ela o antídoto e ela sobrevive sem sequelas. Trata-se de:","opcoes":["Arrependimento eficaz","Arrependimento posterior","Desistência voluntária","Crime impossível"],"explicacao":"A execução terminou, mas o agente impediu o resultado; responde só pelo que já causou."},{"id":5757,"materia":"ppen","nivel":0,"enunciado":"Qual destas NÃO é uma característica do inquérito policial?","opcoes":["Contraditório amplo, como no processo","Escrito","Sigiloso, quando necessário à apuração","Dispensável"],"explicacao":"No inquérito não há contraditório pleno; ele é inquisitivo."},{"id":5758,"materia":"pen","nivel":0,"enunciado":"Um vizinho vê um homem furtando uma bicicleta e o segura até a polícia chegar. Essa conduta é:","opcoes":["Permitida: qualquer pessoa pode prender em flagrante","Crime de sequestro","Proibida a quem não é policial ou agente público de segurança","Abuso de autoridade"],"explicacao":"Art. 301 do CPP: qualquer do povo pode prender quem está em flagrante."},{"id":5759,"materia":"ppen","nivel":2,"enunciado":"Quando alguém é apresentado preso em flagrante, a notícia do crime é chamada de:","opcoes":["Coercitiva","Espontânea","Inqualificada","Provocada"],"explicacao":"A notitia criminis coercitiva vem com a prisão em flagrante."},{"id":5760,"materia":"ppen","nivel":0,"enunciado":"Quando o crime depende de representação, quem pode oferecê-la?","opcoes":["O ofendido ou seu representante legal","Apenas o delegado","Apenas o juiz","Qualquer pessoa do povo que saiba do crime"],"explicacao":"Art. 39 do CPP."},{"id":5761,"materia":"ppen","nivel":0,"enunciado":"A polícia recebe uma denúncia, espera escondida e prende o ladrão no momento do crime, sem tê-lo induzido. Esse flagrante é:","opcoes":["Esperado, e é válido","Preparado, e é nulo","Forjado, e é crime","Impossível, e é nulo"],"explicacao":"No flagrante preparado a polícia induz o crime (Súmula 145 do STF); no esperado, apenas aguarda."},{"id":5762,"materia":"ppen","nivel":1,"enunciado":"Policiais perseguem um suspeito por várias ruas logo após um roubo e o prendem 20 minutos depois. Essa prisão é:","opcoes":["Flagrante impróprio, válido","Ilegal, porque passou muito tempo","Flagrante preparado","Prisão temporária"],"explicacao":"O que importa é a perseguição contínua, iniciada logo após o crime."},{"id":5763,"materia":"ppen","nivel":3,"enunciado":"Pôr frente a frente duas testemunhas cujas declarações divergem é:","opcoes":["Acareação","Reconhecimento","Reprodução simulada","Interrogatório"],"explicacao":"Art. 229 do CPP."},{"id":5764,"materia":"ppen","nivel":1,"enunciado":"Na ação penal privada, o ofendido perde o direito de queixa se não a oferecer em:","opcoes":["6 meses, contados de quando soube quem é o autor","30 dias, contados do crime","1 ano, contado do dia exato em que o crime aconteceu","10 anos, contados do fato"],"explicacao":"É a decadência (art. 38 do CPP)."},{"id":5765,"materia":"ppen","nivel":1,"enunciado":"O mandado de busca domiciliar deve indicar, o mais precisamente possível:","opcoes":["A casa em que será feita a diligência e o nome do morador","Apenas o bairro","Apenas o nome do delegado","Nenhum dado, para garantir o sigilo da diligência policial"],"explicacao":"Art. 243 do CPP."},{"id":5766,"materia":"ppen","nivel":1,"enunciado":"Qual destas é uma prova pericial?","opcoes":["Exame de corpo de delito","Depoimento de testemunha","Interrogatório","Confissão"],"explicacao":"A perícia é feita por perito, com conhecimento técnico."},{"id":5767,"materia":"ppen","nivel":2,"enunciado":"Durante o inquérito, a vítima pede ao delegado que ouça uma testemunha. O delegado:","opcoes":["Pode fazer ou não a diligência, conforme seu juízo","É obrigado a fazer qualquer diligência que a vítima pedir","Precisa de autorização do investigado","Deve arquivar o inquérito"],"explicacao":"Art. 14 do CPP."},{"id":5768,"materia":"ppen","nivel":2,"enunciado":"O delegado concluiu o inquérito de um crime de ação pública. Ele deve:","opcoes":["Remeter os autos ao juiz competente, com relatório","Oferecer a denúncia","Arquivar os autos por conta própria se não achar provas","Devolver à vítima"],"explicacao":"Art. 10, § 1º, do CPP."},{"id":5769,"materia":"ppen","nivel":2,"enunciado":"A identificação criminal do civilmente identificado é possível quando, por exemplo:","opcoes":["O documento apresentar rasura ou indício de falsificação","O suspeito pedir","O crime investigado for de menor potencial ofensivo, sem vítima","For noite"],"explicacao":"Art. 3º da Lei 12.037/2009."},{"id":5770,"materia":"ppen","nivel":3,"enunciado":"O prazo para a conclusão do inquérito policial federal com indiciado preso é de:","opcoes":["15 dias, prorrogáveis por mais 15","10 dias, sem nenhuma possibilidade de prorrogação","30 dias","90 dias"],"explicacao":"Lei 5.010/1966, art. 66."},{"id":5771,"materia":"ppen","nivel":3,"enunciado":"Na Lei de Drogas, o prazo do inquérito com indiciado preso é de 30 dias e pode ser:","opcoes":["Duplicado pelo juiz, ouvido o MP, a pedido justificado da polícia","Reduzido pela vítima","Estendido sem limite pelo delegado","Encerrado em 24 horas"],"explicacao":"Art. 51, parágrafo único, da Lei 11.343/2006."},{"id":5772,"materia":"ppen","nivel":4,"enunciado":"Pelo CPP, as provas cautelares, não repetíveis e antecipadas produzidas no inquérito:","opcoes":["Podem fundamentar a decisão do juiz, mesmo sem contraditório judicial","Nunca podem ser usadas","Só valem se o réu confessar o crime em juízo, diante do juiz e do promotor","Só valem no júri"],"explicacao":"Art. 155 do CPP: são exceções à regra de que o juiz não decide só com base no inquérito."},{"id":5773,"materia":"leg","nivel":0,"enunciado":"Pela Lei Maria da Penha, quebrar o celular da companheira para controlá-la é violência:","opcoes":["Patrimonial","Física","Sexual","Institucional"],"explicacao":"Destruir objetos, documentos ou bens da mulher é violência patrimonial."},{"id":5774,"materia":"leg","nivel":0,"enunciado":"Pela Lei Maria da Penha, a violência doméstica pode ser praticada:","opcoes":["Também por mulher contra mulher","Só por marido","Só por pessoa que mora junto com a vítima","Só por parentes de sangue"],"explicacao":"O que importa é a relação doméstica, familiar ou íntima de afeto."},{"id":5775,"materia":"leg","nivel":1,"enunciado":"Ter uma arma registrada dentro de casa é ___, enquanto andar com ela na rua é ___.","opcoes":["Posse; porte","Porte; posse","Porte; porte","Posse; posse"],"explicacao":"A posse é dentro da residência ou do local de trabalho (se for o responsável)."},{"id":5776,"materia":"leg","nivel":0,"enunciado":"Qual destes crimes é equiparado a hediondo pela Constituição?","opcoes":["Tortura","Furto simples","Ameaça","Dano"],"explicacao":"Também tráfico de drogas e terrorismo."},{"id":5777,"materia":"leg","nivel":3,"enunciado":"Na lavagem de dinheiro, a fase de dar aparência lícita ao dinheiro, trazendo-o de volta à economia formal, é a:","opcoes":["Integração","Colocação","Ocultação","Prescrição"],"explicacao":"As fases são colocação, ocultação (estratificação) e integração."},{"id":5778,"materia":"leg","nivel":1,"enunciado":"Qual destas é uma medida socioeducativa em meio aberto, prevista no ECA?","opcoes":["Liberdade assistida","Internação","Semiliberdade, com atividades externas","Prisão domiciliar"],"explicacao":"Prestação de serviços à comunidade também é em meio aberto."},{"id":5779,"materia":"leg","nivel":1,"enunciado":"Pela Lei de Drogas, ao usuário podem ser aplicadas:","opcoes":["Advertência, prestação de serviços e medida educativa","Reclusão de 5 a 15 anos","Detenção em regime fechado","Pena de morte"],"explicacao":"Art. 28 da Lei 11.343/2006."},{"id":5780,"materia":"leg","nivel":1,"enunciado":"Disparar arma de fogo em via pública, em lugar habitado, sem querer atingir ninguém, é:","opcoes":["Crime de disparo de arma de fogo","Conduta permitida a quem tem porte","Apenas uma contravenção","Tentativa de homicídio, sempre"],"explicacao":"Art. 15 do Estatuto do Desarmamento."},{"id":5781,"materia":"leg","nivel":2,"enunciado":"Pelo CTB, afastar-se do local do acidente para fugir da responsabilidade é:","opcoes":["Crime","Apenas infração leve","Permitido se não houve morte","Permitido à noite"],"explicacao":"Art. 305 do CTB."},{"id":5782,"materia":"leg","nivel":1,"enunciado":"Pela Lei de Abuso de Autoridade, os crimes só se configuram quando o agente age com:","opcoes":["Finalidade específica, como prejudicar alguém ou satisfazer capricho","Simples culpa","Qualquer divergência na interpretação da lei ou na avaliação de fatos e provas","Ordem judicial"],"explicacao":"Art. 1º, § 1º, da Lei 13.869/2019."},{"id":5783,"materia":"leg","nivel":2,"enunciado":"Pela Lei de Abuso de Autoridade, decretar prisão em manifesta desconformidade com a lei é crime que pode ser praticado por:","opcoes":["Autoridade judiciária","Qualquer particular","Apenas o delegado","Apenas o promotor"],"explicacao":"Art. 9º da Lei 13.869/2019."},{"id":5784,"materia":"leg","nivel":2,"enunciado":"Pela Lei de Tortura, submeter preso a sofrimento físico ou mental por ato não previsto em lei é crime que pode ser praticado:","opcoes":["Contra pessoa presa ou sujeita a medida de segurança","Só contra crianças","Só por particulares, nunca por agentes do Estado no exercício da função","Só em presídios federais"],"explicacao":"Art. 1º, § 1º, da Lei 9.455/1997."},{"id":5785,"materia":"leg","nivel":2,"enunciado":"Na Lei 12.850/2013, quem integra organização criminosa armada tem a pena:","opcoes":["Aumentada até a metade","Reduzida de 1/3","Substituída por multa","Igual à do integrante sem arma"],"explicacao":"Art. 2º, § 2º, da Lei 12.850/2013."},{"id":5786,"materia":"pen","nivel":2,"enunciado":"Na coação moral irresistível, quem é punido?","opcoes":["Apenas o autor da coação","Apenas quem foi coagido","Os dois, com a mesma pena","Ninguém"],"explicacao":"Art. 22 do Código Penal."},{"id":5787,"materia":"pen","nivel":2,"enunciado":"Um policial deixa de autuar um amigo por pura amizade, contra o dever do cargo. Ele comete:","opcoes":["Prevaricação","Corrupção passiva","Concussão","Condescendência criminosa"],"explicacao":"Retardar ou deixar de praticar ato de ofício para satisfazer interesse ou sentimento pessoal (art. 319)."},{"id":5788,"materia":"pen","nivel":2,"enunciado":"O preso que foge sem usar violência contra a pessoa:","opcoes":["Não comete o crime de evasão (art. 352), mas sofre falta grave","Comete crime de evasão, mesmo sem violência contra a pessoa, pois fugiu","Comete roubo","Comete resistência"],"explicacao":"O art. 352 exige violência contra a pessoa."},{"id":5789,"materia":"const","nivel":0,"enunciado":"Qual destes é um direito social previsto na Constituição?","opcoes":["Segurança","Pena de morte","Censura","Banimento"],"explicacao":"Art. 6º: educação, saúde, alimentação, trabalho, moradia, transporte, lazer, segurança e outros."},{"id":5790,"materia":"const","nivel":3,"enunciado":"Pela Constituição, os policiais militares e bombeiros são subordinados:","opcoes":["Aos governadores dos estados","Ao Presidente da República","Aos prefeitos","Ao Ministro da Justiça"],"explicacao":"Art. 144, § 6º. São forças auxiliares e reserva do Exército."},{"id":5791,"materia":"const","nivel":0,"enunciado":"A Polícia Federal é mantida pela:","opcoes":["União","Cada estado","Cada município","Iniciativa privada"],"explicacao":"Art. 144, § 1º, da Constituição."},{"id":5792,"materia":"const","nivel":0,"enunciado":"Qual destes órgãos NÃO está no art. 144 da Constituição (segurança pública)?","opcoes":["Ministério Público","Polícia Civil","Polícia Militar","Polícia Rodoviária Federal"],"explicacao":"O MP é função essencial à Justiça, não órgão de segurança pública."},{"id":5793,"materia":"const","nivel":1,"enunciado":"Pela Constituição, a casa pode ser invadida durante a noite, sem consentimento, em caso de:","opcoes":["Flagrante delito, desastre ou para prestar socorro","Ordem judicial escrita, apenas, a qualquer hora da noite","Ordem do delegado","Suspeita genérica"],"explicacao":"A ordem judicial só pode ser cumprida durante o dia."},{"id":5794,"materia":"const","nivel":1,"enunciado":"Pela Constituição, a pena de morte é admitida:","opcoes":["Em caso de guerra declarada","Para crimes hediondos e para terrorismo","Para tráfico internacional","Nunca, em nenhuma hipótese"],"explicacao":"Art. 5º, XLVII, a."},{"id":5795,"materia":"const","nivel":1,"enunciado":"Pela Constituição, a prática do racismo sujeita o autor à pena de:","opcoes":["Reclusão","Detenção","Multa apenas","Advertência"],"explicacao":"Art. 5º, XLII: crime inafiançável e imprescritível."},{"id":5796,"materia":"pen","nivel":1,"enunciado":"O motorista que, ao ler mensagens no celular, atropela e mata um pedestre comete, em regra, homicídio:","opcoes":["Culposo","Doloso qualificado","Privilegiado","Preterdoloso"],"explicacao":"Falta de cuidado (imprudência), sem intenção de matar."},{"id":5797,"materia":"const","nivel":2,"enunciado":"A Constituição permite que os estados criem, por lei, as polícias:","opcoes":["Civis, militares e penais estaduais","Federais","Rodoviárias federais e ferroviárias federais","Judiciárias da União"],"explicacao":"A Polícia Federal e a PRF são da União."},{"id":5798,"materia":"pen","nivel":1,"enunciado":"Dizer a vizinhos que um colega “desviou dinheiro da empresa”, sabendo que é mentira, é:","opcoes":["Calúnia","Injúria","Difamação","Desacato"],"explicacao":"Imputar falsamente um fato definido como crime."},{"id":5799,"materia":"const","nivel":3,"enunciado":"Pela Constituição, a extradição de estrangeiro NÃO será concedida por crime:","opcoes":["Político ou de opinião","De tráfico de drogas","De homicídio","De roubo"],"explicacao":"Art. 5º, LII, da Constituição."},{"id":5800,"materia":"pen","nivel":3,"enunciado":"Usar um carro alheio e devolvê-lo logo, no mesmo estado, sem intenção de ficar com ele, é chamado de:","opcoes":["Furto de uso, que não é crime","Furto qualificado","Roubo impróprio","Apropriação indébita, pois já tinha a posse"],"explicacao":"Falta o ânimo de assenhoramento definitivo."},{"id":5801,"materia":"adm","nivel":1,"enunciado":"Joana tomou posse no cargo, mas não entrou em exercício no prazo legal. Pela Lei 8.112/1990, ela será:","opcoes":["Exonerada do cargo","Demitida por justa causa","Advertida por escrito","Suspensa por 30 dias"],"explicacao":"Art. 15, § 2º. Exoneração não é punição; demissão é."},{"id":5802,"materia":"adm","nivel":0,"enunciado":"O princípio da impessoalidade impede que o administrador:","opcoes":["Favoreça ou persiga pessoas por interesse próprio","Siga a lei","Divulgue seus atos oficiais à população em geral","Busque resultados"],"explicacao":"A atuação deve visar ao interesse público."},{"id":5803,"materia":"adm","nivel":0,"enunciado":"O poder de polícia é exercido, por exemplo, quando a Administração:","opcoes":["Fiscaliza e multa um estabelecimento irregular","Pune um servidor faltoso do próprio órgão público","Edita uma lei","Julga um processo criminal"],"explicacao":"Punir servidor é poder disciplinar."},{"id":5804,"materia":"adm","nivel":4,"enunciado":"Pela Lei 8.112/1990, na suspensão de até 90 dias, a Administração pode convertê-la em multa de:","opcoes":["50% por dia de remuneração, ficando o servidor obrigado a trabalhar","100% do salário","10% da remuneração","Um salário mínimo"],"explicacao":"Art. 130, § 2º, da Lei 8.112/1990."},{"id":5805,"materia":"adm","nivel":1,"enunciado":"A autoexecutoriedade permite que a Administração:","opcoes":["Execute suas decisões sem ordem judicial, em certos casos","Crie leis","Julgue crimes","Cobre tributos sem lei que os institua previamente"],"explicacao":"Ex.: apreender mercadoria estragada ou demolir obra que ameaça desabar."},{"id":5806,"materia":"adm","nivel":1,"enunciado":"Qual destes NÃO é atributo do ato administrativo?","opcoes":["Competência","Imperatividade","Autoexecutoriedade","Presunção de legitimidade"],"explicacao":"Competência é elemento (requisito), não atributo."},{"id":5807,"materia":"adm","nivel":1,"enunciado":"A anulação de um ato administrativo ocorre quando ele é:","opcoes":["Ilegal","Inconveniente","Inoportuno","Antigo"],"explicacao":"Atos inconvenientes ou inoportunos são revogados."},{"id":5808,"materia":"adm","nivel":2,"enunciado":"Improbidade administrativa que causa prejuízo ao erário exige, após a Lei 14.230/2021:","opcoes":["Ação ou omissão dolosa que cause perda patrimonial efetiva","Simples culpa, mesmo sem nenhum prejuízo comprovado ao erário","Apenas desobediência","Nenhum prejuízo"],"explicacao":"Art. 10 da Lei 8.429/1992, com a redação da Lei 14.230/2021."},{"id":5809,"materia":"adm","nivel":2,"enunciado":"Entre as sanções por ato de improbidade estão:","opcoes":["Perda da função pública, suspensão dos direitos políticos e multa","Prisão perpétua","Pena de morte","Cassação da nacionalidade"],"explicacao":"As sanções de improbidade são civis e administrativas, não penais."},{"id":5810,"materia":"adm","nivel":3,"enunciado":"Na Lei 8.112/1990, a demissão do servidor é aplicada, por exemplo, em caso de:","opcoes":["Abandono de cargo","Atraso de 15 minutos","Uma falta justificada","Pedido de férias"],"explicacao":"Abandono de cargo: ausência intencional por mais de 30 dias consecutivos (art. 138)."},{"id":5811,"materia":"adm","nivel":3,"enunciado":"A delegação de competência administrativa:","opcoes":["É possível, salvo vedação legal, e pode ser revogada a qualquer tempo","É sempre proibida","Transfere a titularidade da competência de forma definitiva e irrevogável","Só pode ser feita por lei"],"explicacao":"Arts. 12 e 14 da Lei 9.784/1999."},{"id":5812,"materia":"ppen","nivel":3,"enunciado":"A reconstituição do crime (reprodução simulada) NÃO pode:","opcoes":["Contrariar a moralidade ou a ordem pública","Ser feita pela polícia","Contar com o investigado","Ser filmada"],"explicacao":"Art. 7º do CPP. O investigado não é obrigado a participar."},{"id":5813,"materia":"port","nivel":0,"enunciado":"Em qual frase a palavra “mal” está empregada corretamente?","opcoes":["O suspeito dormiu mal na cela.","Ele é um mal policial.","Foi um mal dia para toda a equipe de plantão.","Que mal humor!"],"explicacao":"Mal é advérbio (oposto de bem); mau é adjetivo (oposto de bom)."},{"id":5814,"materia":"port","nivel":0,"enunciado":"Qual destas frases tem o verbo no plural corretamente?","opcoes":["Os investigadores encontraram a arma.","Os investigadores encontrou a arma.","O investigador encontraram a arma.","Os investigador encontraram a arma."],"explicacao":"O verbo concorda com o sujeito."},{"id":5815,"materia":"port","nivel":1,"enunciado":"Em qual frase NÃO deve haver crase?","opcoes":["Começou a investigar o caso.","Fomos à delegacia.","Entregou o documento à escrivã.","Chegou à noite."],"explicacao":"Não há crase antes de verbo."},{"id":5816,"materia":"port","nivel":1,"enunciado":"Em “O delegado, que estava de plantão, atendeu a ocorrência”, a oração entre vírgulas dá uma:","opcoes":["Explicação sobre o delegado","Condição para que o atendimento acontecesse","Causa da ocorrência","Finalidade do plantão"],"explicacao":"É uma oração adjetiva explicativa."},{"id":5817,"materia":"port","nivel":1,"enunciado":"Qual frase usa corretamente “porque”?","opcoes":["Faltou porque estava doente.","Porque você faltou?","Não sei o porque da falta.","Faltou, por quê estava doente."],"explicacao":"“Porque” junto e sem acento dá a causa, em respostas."},{"id":5818,"materia":"port","nivel":2,"enunciado":"Qual destas frases está na voz ativa?","opcoes":["A polícia prendeu o suspeito.","O suspeito foi preso pela polícia.","Prendeu-se o suspeito.","O suspeito foi detido."],"explicacao":"Na voz ativa, o sujeito pratica a ação."},{"id":5819,"materia":"port","nivel":2,"enunciado":"Em “Encontrei o documento de que precisava”, a preposição “de” é exigida pelo verbo:","opcoes":["Precisar","Encontrar","Ser","Estar"],"explicacao":"Quem precisa, precisa de algo."},{"id":5820,"materia":"port","nivel":3,"enunciado":"Em “Não obstante as provas, o réu foi absolvido”, a expressão “não obstante” pode ser trocada, sem mudar o sentido, por:","opcoes":["Apesar de","Por causa de","Graças a","Em razão de"],"explicacao":"Indica concessão: algo que poderia impedir, mas não impediu."},{"id":5821,"materia":"inf","nivel":0,"enunciado":"Qual destas é uma boa prática de segurança?","opcoes":["Não clicar em links de mensagens desconhecidas","Usar a mesma senha em todos os sites, para não esquecer","Anotar a senha no monitor","Desligar o antivírus"],"explicacao":"Links desconhecidos são a principal porta de golpes."},{"id":5822,"materia":"inf","nivel":0,"enunciado":"Um arquivo com extensão .jpg é, normalmente:","opcoes":["Uma imagem","Um texto do Word","Uma planilha","Um programa"],"explicacao":"PNG e GIF também são formatos de imagem."},{"id":5823,"materia":"inf","nivel":1,"enunciado":"No Excel, a fórmula =MÁXIMO(3;9;5) retorna:","opcoes":["9","3","5","17"],"explicacao":"MÁXIMO devolve o maior valor da lista."},{"id":5824,"materia":"inf","nivel":1,"enunciado":"Na internet, o protocolo usado para transferir páginas web de forma segura é o:","opcoes":["HTTPS","FTP","SMTP","POP3"],"explicacao":"SMTP envia e-mails; POP3 e IMAP recebem."},{"id":5825,"materia":"inf","nivel":2,"enunciado":"Qual destes NÃO é um tipo de malware?","opcoes":["Firewall","Vírus","Trojan (cavalo de Troia)","Spyware"],"explicacao":"O firewall é uma ferramenta de proteção."},{"id":5826,"materia":"inf","nivel":1,"enunciado":"O backup serve principalmente para:","opcoes":["Recuperar os dados em caso de perda","Deixar o computador mais rápido e com mais espaço livre","Remover vírus","Aumentar a memória RAM"],"explicacao":"Cópia de segurança dos arquivos."},{"id":5827,"materia":"rl","nivel":0,"enunciado":"Qual destas proposições é a negação de “O suspeito fugiu”?","opcoes":["O suspeito não fugiu","O suspeito voltou","O suspeito fugiu de novo","Alguém fugiu"],"explicacao":"Basta acrescentar o “não”."},{"id":5828,"materia":"rl","nivel":0,"enunciado":"Se a proposição P é verdadeira, a negação de P é:","opcoes":["Falsa","Verdadeira","Às vezes verdadeira","Impossível de saber"],"explicacao":"A negação inverte o valor lógico."},{"id":5829,"materia":"rl","nivel":2,"enunciado":"Em uma sequência, cada termo é o dobro do anterior: 3, 6, 12, 24... O 6º termo é:","opcoes":["96","48","72","192"],"explicacao":"3, 6, 12, 24, 48, 96."},{"id":5830,"materia":"rl","nivel":1,"enunciado":"Em uma fila, Ana está à frente de Bia, e Bia está à frente de Caio. Quem está mais atrás?","opcoes":["Caio","Ana","Bia","Não dá para saber"],"explicacao":"A ordem é Ana, Bia, Caio."},{"id":5831,"materia":"rl","nivel":2,"enunciado":"Se é FALSO que “algum preso fugiu”, então é verdade que:","opcoes":["Nenhum preso fugiu","Todos os presos fugiram","Algum preso não fugiu","Só um preso fugiu"],"explicacao":"Se nem um único preso fugiu, “nenhum preso fugiu” é verdadeira."},{"id":5832,"materia":"rl","nivel":3,"enunciado":"Se “Se chove, a ronda é cancelada” é verdadeira e a ronda NÃO foi cancelada, pode-se concluir que:","opcoes":["Não choveu","Choveu","A ronda foi cancelada","Nada se pode concluir"],"explicacao":"É o modus tollens: se Q é falso, P também é."},{"id":5833,"materia":"dh","nivel":0,"enunciado":"Qual destes é um direito previsto na Declaração Universal dos Direitos Humanos?","opcoes":["Direito à vida, à liberdade e à segurança pessoal","Direito de escravizar","Direito de torturar","Direito à vingança privada"],"explicacao":"Artigo 3 da Declaração."},{"id":5834,"materia":"dh","nivel":1,"enunciado":"Pela Convenção Americana, ninguém deve ser submetido a:","opcoes":["Torturas nem a penas ou tratamentos cruéis, desumanos ou degradantes","Julgamento por juiz natural e imparcial, previamente definido em lei","Identificação civil","Pagamento de impostos"],"explicacao":"Artigo 5 da Convenção."},{"id":5835,"materia":"dh","nivel":2,"enunciado":"A proibição da tortura é um direito humano:","opcoes":["Absoluto, que não admite exceção nem em guerra","Que pode ser suspenso em estado de emergência nacional","Válido só em tempo de paz","Que depende da gravidade do crime"],"explicacao":"A Convenção contra a Tortura da ONU não admite justificativa alguma."},{"id":5836,"materia":"ml","nivel":0,"enunciado":"Um soco que deixa a pele roxa, sem cortá-la, produz:","opcoes":["Equimose","Ferida incisa","Ferida perfurante","Queimadura"],"explicacao":"A equimose é o extravasamento de sangue sob a pele."},{"id":5837,"materia":"ml","nivel":1,"enunciado":"O exame que procura vestígios de pólvora nas mãos de quem pode ter atirado é o exame:","opcoes":["Residuográfico","Toxicológico","De DNA","Odontológico"],"explicacao":"Busca resíduos de disparo de arma de fogo."},{"id":5838,"materia":"ml","nivel":2,"enunciado":"No tiro encostado ou à queima-roupa, em volta da ferida de entrada costuma haver:","opcoes":["Zona de tatuagem e de esfumaçamento","Bordas viradas para fora, sem resíduos","Nenhuma marca na pele","Somente uma fratura exposta"],"explicacao":"Resíduos de pólvora e fuligem atingem a pele quando a arma está muito próxima."}]$q$::jsonb)
  as x(id integer, materia text, nivel smallint, enunciado text, opcoes jsonb, explicacao text)
on conflict (id) do update set materia = excluded.materia, nivel = excluded.nivel, enunciado = excluded.enunciado, opcoes = excluded.opcoes, explicacao = excluded.explicacao;

select setval(pg_get_serial_sequence('public.questoes', 'id'), (select max(id) from public.questoes));
select materia, count(*) as questoes from public.questoes where materia in ('pen','ppen','leg','const','adm','port','rl','inf','dh','est','cont') group by materia order by materia;
select count(*) as total_de_questoes from public.questoes;
